import { can } from "@/lib/auth";
import { q } from "@/lib/db";
import { loadContext } from "@/lib/booking/availability";
import { getAgent, getFaqs } from "@/lib/business";
import { pageMember } from "@/lib/page";
import { aiProviderInfo } from "@/lib/ai/provider";
import { emailProvider } from "@/lib/notify/providers";
import { fmtDate, minutesToLabel } from "@/lib/time";
import { SettingsPanel } from "@/components/SettingsPanel";

export const metadata = { title: "Settings" };

export default async function SettingsPage({ params }: { params: Promise<{ slug: string }> }) {
  const { slug } = await params;
  const { business, role, user } = await pageMember(slug, "settings");
  const ctx = await loadContext(business.id);
  const [agent, faqs] = await Promise.all([getAgent(business.id), getFaqs(business.id)]);
  const owner = can(role, "team");
  const members = owner ? await q<{ id: string; name: string; email: string; role: string }>("SELECT u.id, u.name, u.email, m.role FROM memberships m JOIN users u ON u.id = m.user_id WHERE m.business_id = $1 ORDER BY m.created_at", [business.id]) : [];
  const invitations = owner ? await q<{ id: string; email: string; role: string }>("SELECT id, email, role FROM invitations WHERE business_id = $1 AND accepted_at IS NULL AND expires_at > now() ORDER BY created_at DESC", [business.id]) : [];

  return (
    <div className="max-w-3xl space-y-5">
      <h1 className="text-3xl font-extrabold">Settings</h1>
      <SettingsPanel
        businessId={business.id}
        business={business}
        policies={ctx.policies}
        hours={ctx.hours.map((h) => ({ weekday: h.weekday, open: minutesToLabel(h.open_min), close: h.close_min === 1440 ? "24:00" : minutesToLabel(h.close_min) }))}
        closures={ctx.closures.map((c) => ({ id: c.id, label: `${fmtDate(c.starts_at, business.timezone)} to ${fmtDate(new Date(c.ends_at.getTime() - 1), business.timezone)}`, reason: c.reason }))}
        resources={ctx.resources.filter((r) => r.active).map((r) => ({ id: r.id, name: r.name, capacity: r.capacity, type: r.type }))}
        services={ctx.services.filter((s) => s.active).map((s) => ({ id: s.id, name: s.name, description: s.description, duration_min: s.duration_min, price_cents: s.price_cents, currency: s.currency, resource_type: s.resource_type }))}
        agent={agent} faqs={faqs}
        ai={aiProviderInfo()} email={{ delivers: emailProvider().delivers, name: emailProvider().name }}
        team={owner ? { members, invitations, me: user.id } : null}
      />
    </div>
  );
}
