import type { PoolClient } from "pg";
import { one, q, tx, pgCode } from "./db";
import { AppError, invalid } from "./errors";
import { labelToMinutes } from "./time";
import { audit } from "./audit";
import { BUSINESS_COLUMNS, type Business } from "./booking/availability";
import type { CreateBusinessInput, SettingsInput } from "./schemas";

const RESOURCE_NOUN: Record<string, { type: string; noun: string; service: string }> = {
  restaurant: { type: "table", noun: "Table", service: "Table reservation" },
  salon: { type: "staff", noun: "Stylist", service: "Appointment" },
  clinic: { type: "staff", noun: "Practitioner", service: "Consultation" },
  hotel: { type: "room", noun: "Room", service: "Room booking" },
  repair: { type: "staff", noun: "Technician", service: "Service appointment" },
  other: { type: "slot", noun: "Slot", service: "Booking" },
};

export function slugify(name: string): string {
  const s = name.toLowerCase().normalize("NFKD").replace(/[̀-ͯ]/g, "").replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "").slice(0, 40);
  return s.length >= 3 ? s : `business-${s}`.replace(/-$/, "");
}

function parseHours(hours: { weekday: number; open: string; close: string }[]) {
  const out = hours.map((h) => ({ weekday: h.weekday, open_min: labelToMinutes(h.open)!, close_min: labelToMinutes(h.close)! }));
  for (const h of out) if (h.close_min <= h.open_min) throw invalid("Closing time must be after opening time (hours past midnight are not supported yet).");
  for (const a of out) for (const b of out) {
    if (a !== b && a.weekday === b.weekday && a.open_min < b.close_min && b.open_min < a.close_min) throw invalid("Opening periods on the same day overlap.");
  }
  return out;
}

async function setPolicies(db: PoolClient, businessId: string, p: Record<string, unknown>) {
  const keys = Object.keys(p).filter((k) => p[k] !== undefined);
  if (!keys.length) return;
  // Keys come from a strict zod schema, never from raw input.
  const sets = keys.map((k, i) => `${k} = $${i + 2}`).join(", ");
  await db.query(`UPDATE business_policies SET ${sets} WHERE business_id = $1`, [businessId, ...keys.map((k) => p[k])]);
}

export async function createBusiness(userId: string, input: CreateBusinessInput): Promise<Business> {
  const hours = parseHours(input.hours);
  const kind = RESOURCE_NOUN[input.type];
  const base = slugify(input.name);
  for (let attempt = 0; attempt < 6; attempt++) {
    const slug = attempt === 0 ? base : `${base}-${Math.random().toString(36).slice(2, 6)}`;
    try {
      return await tx(async (db) => {
        const b = (await one<{ id: string }>(
          `INSERT INTO businesses (slug, name, type, timezone, description, address, phone, contact_email)
           VALUES ($1,$2,$3,$4,$5,$6,$7,$8) RETURNING id`,
          [slug, input.name, input.type, input.timezone, input.description, input.address, input.phone, input.contact_email], db))!;
        await db.query("INSERT INTO memberships (user_id, business_id, role) VALUES ($1,$2,'owner')", [userId, b.id]);
        await db.query("INSERT INTO business_policies (business_id) VALUES ($1)", [b.id]);
        await setPolicies(db, b.id, input.policies);
        await db.query("INSERT INTO agent_configs (business_id) VALUES ($1)", [b.id]);
        await setAgent(db, b.id, input.agent);
        await db.query("INSERT INTO services (business_id, name, resource_type) VALUES ($1,$2,$3)", [b.id, input.service_name || kind.service, kind.type]);
        for (const h of hours) await db.query("INSERT INTO opening_hours (business_id, weekday, open_min, close_min) VALUES ($1,$2,$3,$4)", [b.id, h.weekday, h.open_min, h.close_min]);
        let n = 0;
        for (const row of input.capacity) {
          for (let i = 0; i < row.count; i++) {
            n++;
            await db.query("INSERT INTO resources (business_id, type, name, capacity, sort) VALUES ($1,$2,$3,$4,$5)",
              [b.id, kind.type, `${row.label || kind.noun} ${n}`, row.capacity, n]);
          }
        }
        await audit({ businessId: b.id, userId, action: "business.created" }, db);
        return (await one<Business>(`SELECT ${BUSINESS_COLUMNS} FROM businesses b WHERE b.id = $1`, [b.id], db))!;
      });
    } catch (e) {
      if (pgCode(e) === "23505" && (e as { constraint?: string }).constraint === "businesses_slug_key") continue;
      throw e;
    }
  }
  throw new AppError("slug_taken", "Could not create a unique address for this business. Try a slightly different name.", 409);
}

async function setAgent(db: PoolClient, businessId: string, a: Record<string, unknown>) {
  const keys = Object.keys(a).filter((k) => a[k] !== undefined);
  if (!keys.length) return;
  const sets = keys.map((k, i) => `${k} = $${i + 2}`).join(", ");
  await db.query(`UPDATE agent_configs SET ${sets} WHERE business_id = $1`, [businessId, ...keys.map((k) => a[k])]);
}

/** Apply any subset of settings in one transaction. */
export async function updateSettings(businessId: string, userId: string, s: SettingsInput): Promise<void> {
  const hours = s.hours ? parseHours(s.hours) : null;
  await tx(async (db) => {
    if (s.profile) {
      const keys = Object.keys(s.profile).filter((k) => (s.profile as Record<string, unknown>)[k] !== undefined);
      if (keys.length) {
        const sets = keys.map((k, i) => `${k} = $${i + 2}`).join(", ");
        await db.query(`UPDATE businesses SET ${sets} WHERE id = $1`, [businessId, ...keys.map((k) => (s.profile as Record<string, unknown>)[k])]);
      }
    }
    if (s.online_booking_enabled !== undefined) await db.query("UPDATE businesses SET online_booking_enabled = $2 WHERE id = $1", [businessId, s.online_booking_enabled]);
    if (s.ai_enabled !== undefined) await db.query("UPDATE businesses SET ai_enabled = $2 WHERE id = $1", [businessId, s.ai_enabled]);
    if (s.policies) await setPolicies(db, businessId, s.policies);
    if (s.agent) await setAgent(db, businessId, s.agent);
    if (hours) {
      await db.query("DELETE FROM opening_hours WHERE business_id = $1", [businessId]);
      for (const h of hours) await db.query("INSERT INTO opening_hours (business_id, weekday, open_min, close_min) VALUES ($1,$2,$3,$4)", [businessId, h.weekday, h.open_min, h.close_min]);
    }
    if (s.faqs) {
      await db.query("DELETE FROM faqs WHERE business_id = $1", [businessId]);
      let i = 0;
      for (const f of s.faqs) await db.query("INSERT INTO faqs (business_id, question, answer, sort) VALUES ($1,$2,$3,$4)", [businessId, f.question, f.answer, i++]);
    }
    if (s.resources) {
      // Resources referenced by past bookings are never deleted, only retired.
      const keep = s.resources.filter((r) => r.id).map((r) => r.id);
      await db.query("UPDATE resources SET active = false WHERE business_id = $1 AND NOT (id = ANY($2::uuid[]))", [businessId, keep]);
      let i = 0;
      for (const r of s.resources) {
        i++;
        if (r.id) await db.query("UPDATE resources SET name = $3, capacity = $4, type = $5, active = true, sort = $6 WHERE business_id = $1 AND id = $2", [businessId, r.id, r.name, r.capacity, r.type, i]);
        else await db.query("INSERT INTO resources (business_id, name, capacity, type, sort) VALUES ($1,$2,$3,$4,$5)", [businessId, r.name, r.capacity, r.type, i]);
      }
    }
    if (s.services) {
      const keep = s.services.filter((r) => r.id).map((r) => r.id);
      await db.query("UPDATE services SET active = false WHERE business_id = $1 AND NOT (id = ANY($2::uuid[]))", [businessId, keep]);
      let i = 0;
      for (const v of s.services) {
        i++;
        const args = [v.name, v.description, v.duration_min, v.price_cents, v.currency, v.resource_type, i];
        if (v.id) await db.query("UPDATE services SET name=$3, description=$4, duration_min=$5, price_cents=$6, currency=$7, resource_type=$8, sort=$9, active=true WHERE business_id=$1 AND id=$2", [businessId, v.id, ...args]);
        else await db.query("INSERT INTO services (business_id, name, description, duration_min, price_cents, currency, resource_type, sort) VALUES ($1,$2,$3,$4,$5,$6,$7,$8)", [businessId, ...args]);
      }
    }
    await audit({ businessId, userId, action: "settings.updated", detail: { sections: Object.keys(s) } }, db);
  });
}

export async function getPublicBusiness(slug: string): Promise<Business | null> {
  if (!/^[a-z0-9-]{3,50}$/.test(slug)) return null;
  return one<Business>(`SELECT ${BUSINESS_COLUMNS} FROM businesses b WHERE b.slug = $1`, [slug]);
}

export type AgentConfig = { name: string; tone: string; languages: string[]; greeting: string; extra_instructions: string; handoff_contact: string };
export const getAgent = async (businessId: string) => (await one<AgentConfig>("SELECT name, tone, languages, greeting, extra_instructions, handoff_contact FROM agent_configs WHERE business_id = $1", [businessId]))!;
export const getFaqs = (businessId: string) => q<{ question: string; answer: string }>("SELECT question, answer FROM faqs WHERE business_id = $1 ORDER BY sort", [businessId]);

// ---- logo upload ---------------------------------------------------------------
const SIGNATURES: { mime: string; test: (b: Buffer) => boolean }[] = [
  { mime: "image/png", test: (b) => b.subarray(0, 8).equals(Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a])) },
  { mime: "image/jpeg", test: (b) => b[0] === 0xff && b[1] === 0xd8 && b[2] === 0xff },
  { mime: "image/webp", test: (b) => b.subarray(0, 4).toString() === "RIFF" && b.subarray(8, 12).toString() === "WEBP" },
];

/**
 * Store an uploaded logo. The type is decided from the file's own bytes, not from the name or the
 * browser-supplied content type. SVG is refused because it can carry scripts.
 */
export async function saveLogo(businessId: string, userId: string, bytes: Buffer): Promise<void> {
  if (bytes.length === 0) throw invalid("The file is empty.");
  if (bytes.length > 1_000_000) throw new AppError("too_large", "Logo must be smaller than 1 MB.", 413);
  const sig = SIGNATURES.find((s) => s.test(bytes));
  if (!sig) throw invalid("Logo must be a PNG, JPEG or WebP image.");
  await q("UPDATE businesses SET logo = $2, logo_mime = $3 WHERE id = $1", [businessId, bytes, sig.mime]);
  await audit({ businessId, userId, action: "logo.updated" });
}

/** Erase a customer's personal data on request. Reservations stay for the record, without identity. */
export async function eraseCustomer(businessId: string, userId: string, customerId: string): Promise<boolean> {
  return tx(async (db) => {
    const live = await one("SELECT 1 FROM reservations WHERE business_id = $1 AND customer_id = $2 AND status IN ('pending','confirmed') AND starts_at > now() LIMIT 1", [businessId, customerId], db);
    if (live) throw new AppError("has_upcoming", "Cancel this customer's upcoming reservations before deleting their data.", 409);
    const res = await db.query(
      "UPDATE customers SET name = 'Deleted customer', email = NULL, phone = NULL, notify_consent = false, erased_at = now() WHERE business_id = $1 AND id = $2 AND erased_at IS NULL",
      [businessId, customerId]);
    if (!res.rowCount) return false;
    await db.query("UPDATE reservations SET notes = '' WHERE business_id = $1 AND customer_id = $2", [businessId, customerId]);
    await db.query("UPDATE notification_jobs SET status = 'cancelled', recipient = '' WHERE business_id = $1 AND reservation_id IN (SELECT id FROM reservations WHERE customer_id = $2) AND status = 'queued'", [businessId, customerId]);
    await db.query("UPDATE notification_jobs SET recipient = '' WHERE business_id = $1 AND reservation_id IN (SELECT id FROM reservations WHERE customer_id = $2)", [businessId, customerId]);
    // Chat transcripts of their bookings contain what they typed (name, email, phone): remove them too.
    await db.query("DELETE FROM messages WHERE conversation_id IN (SELECT c.id FROM conversations c JOIN reservations r ON r.id = c.reservation_id WHERE r.business_id = $1 AND r.customer_id = $2)", [businessId, customerId]);
    await db.query("UPDATE conversations SET escalation = NULL WHERE business_id = $1 AND reservation_id IN (SELECT id FROM reservations WHERE customer_id = $2)", [businessId, customerId]);
    await audit({ businessId, userId, action: "customer.erased", entity: "customer", entityId: customerId }, db);
    return true;
  });
}
